    const { getCachedChildren, getCachedTrashed, loadChildren, loadTrashedLinks } = useLinksListing();
    const { moveLinks } = useLinksActions();
    const [countOfUnrecoveredLinksLeft, setCountOfUnrecoveredLinksLeft] = useState<number>(0);
    const [countOfFailedLinks, setCountOfFailedLinks] = useState<number>(0);
    const [state, setState] = useState<RECOVERY_STATE>('READY');
    const [restoredData, setRestoredData] = useState<{ links: DecryptedLink[]; shareId: string }[]>([]);
    const [needsRecovery, setNeedsRecovery] = useState<boolean>(false);

    const [restoredShares, setRestoredShares] = useState<Share[] | ShareWithKey[] | undefined>();

    useEffect(() => {
        const shares = getRestoredPhotosShares();
        setRestoredShares(shares);
        setNeedsRecovery(!!shares?.length);
    }, [getRestoredPhotosShares]);
    const handleFailed = useCallback((error: unknown) => {
        setState('FAILED');
        setItem(RECOVERY_STATE_CACHE_KEY, 'failed');
        sendErrorReport(error instanceof Error ? error : new Error('Photos recovery failed'));
    }, []);

    const handleDecryptLinks = useCallback(
        async (
            abortSignal: AbortSignal,
            shares: Share[] | ShareWithKey[],
            includeTrashedItems = false
        ) => {
            const volumeIds = getUniqueVolumeIds(shares);
            await Promise.all([
                ...shares.map((share) => loadChildren(abortSignal, share.shareId, share.rootLinkId)),
                ...(includeTrashedItems ? volumeIds.map((volumeId) => loadTrashedLinks(abortSignal, volumeId)) : []),
            ]);

            await waitFor(
                () => {
                    const regularSourcesAreDecrypted = shares.every(
                        (share) => !getCachedChildren(abortSignal, share.shareId, share.rootLinkId).isDecrypting
                    );
                    const trashedSourcesAreDecrypted =
                        !includeTrashedItems ||
                        volumeIds.every((volumeId) => !getCachedTrashed(abortSignal, volumeId).isDecrypting);
                    return regularSourcesAreDecrypted && trashedSourcesAreDecrypted;
                },
                { abortSignal }
            );
        },
        [getCachedChildren, getCachedTrashed, loadChildren, loadTrashedLinks]
    );

    const handlePrepareLinks = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[]) => {
            const linksByShareId = new Map<string, DecryptedLink[]>();

            for (const share of shares) {
                const { links } = getCachedChildren(abortSignal, share.shareId, share.rootLinkId);
                linksByShareId.set(share.shareId, [...(linksByShareId.get(share.shareId) || []), ...links]);
            }

            for (const volumeId of getUniqueVolumeIds(shares)) {
                const { links } = getCachedTrashed(abortSignal, volumeId);
                for (const link of links.filter(isPhotoLink)) {
                    linksByShareId.set(link.rootShareId, [...(linksByShareId.get(link.rootShareId) || []), link]);
                }
            }

            const allRestoredData = Array.from(linksByShareId, ([shareId, links]) => ({ shareId, links })).filter(
                ({ links }) => links.length > 0
            );
            const totalNbLinks = allRestoredData.reduce((total, { links }) => total + links.length, 0);
            return { allRestoredData, totalNbLinks };
        },
        [getCachedChildren, getCachedTrashed]
    );

    const safelyDeleteShares = useCallback(
        async (abortSignal: AbortSignal, shares: Share[] | ShareWithKey[]) => {
            const volumeIds = getUniqueVolumeIds(shares);
            let regularLinksByShare: { share: Share | ShareWithKey; links: DecryptedLink[] }[] = [];
            let trashedLinksByVolume: DecryptedLink[][] = [];

            await waitFor(
                () => {
                    regularLinksByShare = shares.map((share) => ({
                        share,
                        links: getCachedChildren(abortSignal, share.shareId, share.rootLinkId).links,
                    }));
                    trashedLinksByVolume = volumeIds.map(
                        (volumeId) => getCachedTrashed(abortSignal, volumeId).links
                    );
                    const regularSourcesAreDecrypted = shares.every(
                        (share) => !getCachedChildren(abortSignal, share.shareId, share.rootLinkId).isDecrypting
                    );
                    const trashedSourcesAreDecrypted = volumeIds.every(
                        (volumeId) => !getCachedTrashed(abortSignal, volumeId).isDecrypting
                    );
                    return regularSourcesAreDecrypted && trashedSourcesAreDecrypted;
                },
                { abortSignal }
            );

            const allTrashedLinks = trashedLinksByVolume.flat();
            const remainingPhotoLinks = allTrashedLinks.filter(isPhotoLink);
            const remainingCount =
                regularLinksByShare.reduce((total, { links }) => total + links.length, 0) + remainingPhotoLinks.length;
            setCountOfUnrecoveredLinksLeft(remainingCount);

            let deleteError: unknown;
            for (const share of shares) {
                const regularLinks = regularLinksByShare.find(({ share: currentShare }) => currentShare.shareId === share.shareId)
                    ?.links;
                const hasTrashedLinks = allTrashedLinks.some((link) => link.rootShareId === share.shareId);
                if (!regularLinks?.length && !hasTrashedLinks) {
                    try {
                        await deletePhotosShare(share.volumeId, share.shareId);
                    } catch (error) {
                        deleteError ??= error;
                    }
                }
            }

            if (deleteError) {
                throw deleteError;
            }
            return remainingCount;
        },
        [deletePhotosShare, getCachedChildren, getCachedTrashed]
    );

    const handleMoveLinks = useCallback(
        async (
            abortSignal: AbortSignal,
            {
                dataList,
                newLinkId,
            }: {
                dataList: { links: DecryptedLink[]; shareId: string }[];
                newLinkId: string;
            }
        ) => {
            for (let index = 0; index < dataList.length; index++) {
                const data = dataList[index];
                const handledLinkIds = new Set<string>();
                const markMoved = (linkId: string) => {
                    if (handledLinkIds.has(linkId)) {
                        return;
                    }
                    handledLinkIds.add(linkId);
                    setCountOfUnrecoveredLinksLeft((previousCount) => Math.max(0, previousCount - 1));
                };
                const markFailed = (linkId: string) => {
                    if (handledLinkIds.has(linkId)) {
                        return;
                    }
                    handledLinkIds.add(linkId);
                    setCountOfFailedLinks((previousCount) => previousCount + 1);
                };

                if (!data.links.length) {
                    continue;
                }

                try {
                    await moveLinks(abortSignal, {
                        shareId: data.shareId,
                        linkIds: data.links.map((link) => link.linkId),
                        newParentLinkId: newLinkId,
                        newShareId: shareId,
                        onMoved: markMoved,
                        onError: markFailed,
                    });

                    // A completed move call should report each item through one of its callbacks.
                    data.links.forEach((link) => markFailed(link.linkId));
                } catch (error) {
                    data.links.forEach((link) => markFailed(link.linkId));
                    dataList.slice(index + 1).forEach(({ links }) => links.forEach((link) => markFailed(link.linkId)));
                    throw error;
                }
            }
        },
        [moveLinks, shareId]
    );

    useEffect(() => {
        if (state !== 'STARTED' || !linkId || !restoredShares) {
            return;
        }
        const abortController = new AbortController();
        setState('DECRYPTING');
        void handleDecryptLinks(abortController.signal, restoredShares, true)
            .then(() => {
                setState('DECRYPTED');
            })
            .catch((error) => {
                const failedCount = countCachedRecoveryLinks(abortController.signal, restoredShares, {
                    getCachedChildren,
                    getCachedTrashed,
                });
                setCountOfUnrecoveredLinksLeft(failedCount);
                setCountOfFailedLinks(failedCount);
                abortController.abort();
                handleFailed(error);
            });
    }, [getCachedChildren, getCachedTrashed, handleDecryptLinks, handleFailed, linkId, restoredShares, state]);

    useEffect(() => {
        const abortController = new AbortController();
        if (state !== 'DECRYPTED' || !restoredShares) {
            return;
        }
        setState('PREPARING');
        void handlePrepareLinks(abortController.signal, restoredShares)
            .then(({ allRestoredData, totalNbLinks }) => {
                setRestoredData(allRestoredData);
                setCountOfUnrecoveredLinksLeft(totalNbLinks);
                setCountOfFailedLinks(0);
                setState('PREPARED');
            })
            .catch(handleFailed);
        return () => {
            abortController.abort();
        };
    }, [handlePrepareLinks, restoredShares, state]);

    useEffect(() => {
        if (state !== 'PREPARED' || !linkId) {
            return;
        }
        const abortController = new AbortController();
        setState('MOVING');
        void handleMoveLinks(abortController.signal, {
            newLinkId: linkId,
            dataList: restoredData,
        })
            .then(() => {
                setState('MOVED');
            })
            .catch(handleFailed);

        // Moved is done in the background, so we don't abort it on rerender
    }, [countOfUnrecoveredLinksLeft, handleMoveLinks, linkId, restoredData, state]);

    useEffect(() => {
        if (state !== 'MOVED' || !restoredShares) {
            return;
        }
        const abortController = new AbortController();
        setState('CLEANING');
        void safelyDeleteShares(abortController.signal, restoredShares)
            .then((remainingCount) => {
                if (countOfFailedLinks || remainingCount) {
                    throw new Error('Failed to move recovered photos');
                }
                removeItem(RECOVERY_STATE_CACHE_KEY);
                setState('SUCCEED');
            })
            .catch(handleFailed);

        return () => {
            abortController.abort();
        };
    }, [countOfFailedLinks, restoredShares, safelyDeleteShares, state]);

    const start = useCallback(() => {
        setItem(RECOVERY_STATE_CACHE_KEY, 'progress');
        setCountOfUnrecoveredLinksLeft(0);
        setCountOfFailedLinks(0);
        setState('STARTED');
    }, []);

    useEffect(() => {
        if (state !== 'READY') {
            return;
        }
        const cachedRecoveryState = getItem(RECOVERY_STATE_CACHE_KEY);
        if (cachedRecoveryState === 'progress') {
            setState('STARTED');
        } else if (cachedRecoveryState === 'failed') {
            setState('FAILED');
        }
    }, [state]);
    return {
        needsRecovery,
        countOfUnrecoveredLinksLeft,
        countOfFailedLinks,
        start,
        state,
    };
};

const getUniqueVolumeIds = (shares: (Share | ShareWithKey)[]) => Array.from(new Set(shares.map(({ volumeId }) => volumeId)));

const isPhotoLink = (link: DecryptedLink) =>
    link.isFile && (link.mimeType.startsWith('image/') || link.mimeType.startsWith('video/'));

const countCachedRecoveryLinks = (
    abortSignal: AbortSignal,
    shares: (Share | ShareWithKey)[],
    {
        getCachedChildren,
        getCachedTrashed,
    }: {
        getCachedChildren: ReturnType<typeof useLinksListing>['getCachedChildren'];
        getCachedTrashed: ReturnType<typeof useLinksListing>['getCachedTrashed'];
    }
) => {
    let count = 0;
    for (const share of shares) {
        try {
            count += getCachedChildren(abortSignal, share.shareId, share.rootLinkId)?.links.length || 0;
        } catch {
            // Preserve counts from any source that was available when another source failed.
        }
    }
    for (const volumeId of getUniqueVolumeIds(shares)) {
        try {
            count += getCachedTrashed(abortSignal, volumeId)?.links.filter(isPhotoLink).length || 0;
        } catch {
            // Preserve counts from any source that was available when another source failed.
        }
    }
    return count;
};

